// =====================================================================
// Config & Safety Gate
// Reads every setting from environment variables, validates it and
// computes the effective safety gate. Secrets are NEVER copied into the
// execution data: only "is it set?" booleans leave this node.
// Anything missing, unreadable or invalid falls back to the SAFE default.
// =====================================================================
let envAccessBlocked = false;
const gateWarnings = [];
const configErrors = [];
const gateReasons = [];

const readEnv = (key) => {
  try {
    const v = $env[key];
    if (v === undefined || v === null) return undefined;
    const s = String(v).trim();
    return s === '' ? undefined : s;
  } catch (e) {
    envAccessBlocked = true;
    return undefined;
  }
};
const isSet = (key) => readEnv(key) !== undefined;
const bool = (key, safeDefault) => {
  const v = readEnv(key);
  if (v === undefined) return safeDefault;
  const s = v.toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(s)) return true;
  if (['false', '0', 'no', 'off'].includes(s)) return false;
  gateWarnings.push(`${key}="${v}" is not a boolean; using safe default ${safeDefault}.`);
  return safeDefault;
};
const num = (key, def, min, max) => {
  const v = readEnv(key);
  if (v === undefined) return def;
  const n = Number(v);
  if (!Number.isFinite(n) || n < min || n > max) {
    gateWarnings.push(`${key}="${v}" is outside [${min}, ${max}]; using default ${def}.`);
    return def;
  }
  return n;
};
const str = (key, def) => readEnv(key) ?? def;
const list = (key, def) => (readEnv(key) ?? def).split(',').map((s) => s.trim()).filter(Boolean);

// ---- Safety flags (safe by default) --------------------------------
const requestedSandbox = bool('SANDBOX_MODE', true);
const requestedDryRun = bool('DRY_RUN', true);
const creationEnabled = bool('RENEWAL_DEALS_CREATION_ENABLED', false);
const stageUpdatesEnabled = bool('RENEWAL_STAGE_UPDATES_ENABLED', false);
const writebackEnabled = bool('MILESTONE_WRITEBACK_ENABLED', false);
const sendSlackAlerts = bool('SEND_SLACK_ALERTS', false);
const sendWebhookAlerts = bool('SEND_WEBHOOK_ALERTS', false);

// ---- Secret presence checks (values never output) ------------------
const hasHubspotToken = isSet('HUBSPOT_ACCESS_TOKEN');
const slackUrl = readEnv('SLACK_RENEWAL_WEBHOOK_URL');
const webhookUrl = readEnv('ALERT_WEBHOOK_URL');
const hasSlackWebhook = Boolean(slackUrl) && /^https:\/\//i.test(slackUrl);
const hasAlertWebhook = Boolean(webhookUrl) && /^https:\/\//i.test(webhookUrl);
if (slackUrl && !hasSlackWebhook) gateWarnings.push('SLACK_RENEWAL_WEBHOOK_URL must start with https:// — Slack alerts disabled.');
if (webhookUrl && !hasAlertWebhook) gateWarnings.push('ALERT_WEBHOOK_URL must start with https:// — webhook alerts disabled.');

// ---- HubSpot mapping (non-secret) ----------------------------------
const hubspot = {
  apiBaseUrl: str('HUBSPOT_API_BASE_URL', 'https://api.hubapi.com').replace(/\/+$/, ''),
  portalId: str('HUBSPOT_PORTAL_ID', '99000001'),
  sourcePipelineId: str('HUBSPOT_SOURCE_PIPELINE_ID', 'default'),
  sourceWonStageIds: list('HUBSPOT_SOURCE_CLOSED_WON_STAGE_IDS', 'closedwon'),
  renewalPipelineId: str('HUBSPOT_RENEWAL_PIPELINE_ID', '880001'),
  stageMap: {
    90: str('RENEWAL_STAGE_90_ID', '880001-identified'),
    60: str('RENEWAL_STAGE_60_ID', '880001-proposal'),
    30: str('RENEWAL_STAGE_30_ID', '880001-commit'),
  },
  renewalClosedStageIds: list('HUBSPOT_RENEWAL_CLOSED_STAGE_IDS', '880001-won,880001-lost'),
  associationTypeId: num('HUBSPOT_DEAL_COMPANY_ASSOCIATION_TYPE_ID', 5, 1, 100000),
  fallbackOwnerId: str('RENEWAL_FALLBACK_OWNER_ID', '70000099'),
  props: {
    contractEndDate: str('HUBSPOT_CONTRACT_END_DATE_PROPERTY', 'contract_end_date'),
    arr: str('HUBSPOT_ARR_PROPERTY', 'arr'),
    renewalSourceDealId: str('HUBSPOT_RENEWAL_SOURCE_PROPERTY', 'renewal_source_deal_id'),
    renewalKey: str('HUBSPOT_RENEWAL_KEY_PROPERTY', 'renewal_idempotency_key'),
    lastMilestone: str('HUBSPOT_LAST_MILESTONE_PROPERTY', 'renewal_radar_last_milestone'),
    companyTier: str('HUBSPOT_COMPANY_TIER_PROPERTY', 'customer_tier'),
  },
  maxPages: num('HUBSPOT_MAX_SEARCH_PAGES', 50, 1, 100),
};

// ---- Radar rules ---------------------------------------------------
const windows = [...new Set(list('RENEWAL_WINDOWS_DAYS', '90,60,30').map(Number))]
  .filter((n) => Number.isInteger(n) && n > 0 && n <= 365)
  .sort((a, b) => b - a);
if (!windows.length) configErrors.push('RENEWAL_WINDOWS_DAYS must contain at least one whole number of days between 1 and 365.');
for (const w of windows) {
  if (!hubspot.stageMap[w]) {
    const v = readEnv(`RENEWAL_STAGE_${w}_ID`);
    if (v) hubspot.stageMap[w] = v;
    else configErrors.push(`Window ${w}d has no stage mapping — set RENEWAL_STAGE_${w}_ID.`);
  }
}
const requestedCatchup = num('WINDOW_CATCHUP_DAYS', 2, 0, 14);
const catchupDays = writebackEnabled ? requestedCatchup : 0;
if (!writebackEnabled && requestedCatchup > 0) gateWarnings.push('MILESTONE_WRITEBACK_ENABLED=false — catch-up disabled (exact-day milestones only) so no alert repeats.');

const refEnv = readEnv('RADAR_REFERENCE_DATE');
let referenceDate = new Date().toISOString().slice(0, 10);
let referenceDateSource = 'today_utc';
if (refEnv) {
  if (/^\d{4}-\d{2}-\d{2}$/.test(refEnv) && !Number.isNaN(Date.parse(`${refEnv}T00:00:00Z`))) { referenceDate = refEnv; referenceDateSource = 'RADAR_REFERENCE_DATE'; }
  else gateWarnings.push(`RADAR_REFERENCE_DATE="${refEnv}" is not YYYY-MM-DD; using today (UTC).`);
}

const radar = {
  windows,
  catchupDays,
  provisionWithinDays: windows.length ? windows[0] : 90,
  referenceDate,
  referenceDateSource,
  enterpriseMinArr: num('ENTERPRISE_MIN_ARR', 50000, 0, 1e12),
  enterpriseTierValues: list('ENTERPRISE_TIER_VALUES', 'Enterprise,Strategic').map((s) => s.toLowerCase()),
  associationMatchToleranceDays: num('RENEWAL_MATCH_TOLERANCE_DAYS', 45, 0, 365),
  upliftPct: num('RENEWAL_UPLIFT_PCT', 0, -100, 500),
  dealNameTemplate: str('RENEWAL_DEAL_NAME_TEMPLATE', '{company_name} - Renewal {contract_end_year}'),
  currency: str('RENEWAL_CURRENCY', 'USD'),
};

const limits = {
  maxRenewalDealsPerRun: num('MAX_RENEWAL_DEALS_PER_RUN', 25, 1, 1000),
  circuitBreakerMaxProposed: num('CIRCUIT_BREAKER_MAX_PROPOSED_DEALS', 75, 1, 10000),
  circuitBreakerInvalidDatePct: num('CIRCUIT_BREAKER_INVALID_DATE_PCT', 20, 1, 100),
  batchSize: num('HUBSPOT_BATCH_SIZE', 100, 1, 100),
};

const alerts = {
  minSeverity: str('ALERT_MIN_SEVERITY', 'WARNING').toUpperCase(),
  maxItemsPerSection: num('ALERT_MAX_ITEMS_PER_SECTION', 10, 1, 25),
};
if (!['INFO', 'WARNING', 'CRITICAL'].includes(alerts.minSeverity)) { gateWarnings.push(`ALERT_MIN_SEVERITY="${alerts.minSeverity}" is invalid; using WARNING.`); alerts.minSeverity = 'WARNING'; }

// ---- Effective safety gate -----------------------------------------
let sandboxMode = requestedSandbox;
if (envAccessBlocked) gateReasons.push('Environment access is blocked in this n8n instance (N8N_BLOCK_ENV_ACCESS_IN_NODE). All settings fell back to safe defaults.');
if (!sandboxMode && !hasHubspotToken) { sandboxMode = true; gateReasons.push('SANDBOX_MODE=false but HUBSPOT_ACCESS_TOKEN is not set — forced back to sandbox.'); }
if (!sandboxMode && !/^https:\/\//i.test(hubspot.apiBaseUrl)) { sandboxMode = true; gateReasons.push('HUBSPOT_API_BASE_URL must use https:// — forced back to sandbox.'); }

// Live writes need the renewal pipeline and stages set explicitly (never the mock defaults).
const mappingExplicit = isSet('HUBSPOT_RENEWAL_PIPELINE_ID') && windows.every((w) => isSet(`RENEWAL_STAGE_${w}_ID`)) && isSet('HUBSPOT_PORTAL_ID');
if (!sandboxMode && !mappingExplicit) gateReasons.push('Renewal pipeline, stage IDs or portal ID still use mock defaults — live writes disabled until HUBSPOT_RENEWAL_PIPELINE_ID, HUBSPOT_PORTAL_ID and RENEWAL_STAGE_<window>_ID are set.');
if (configErrors.length) gateReasons.push(`Configuration errors found (${configErrors.length}) — live writes disabled.`);

const dryRun = requestedDryRun || sandboxMode;
const writesBase = !sandboxMode && !requestedDryRun && mappingExplicit && configErrors.length === 0;
const permissions = {
  createRenewalDeals: writesBase && creationEnabled,
  updateRenewalStages: writesBase && stageUpdatesEnabled,
  milestoneWriteback: writesBase && writebackEnabled,
};
if (sandboxMode) gateReasons.push('SANDBOX_MODE=true — mock fixture data, zero network calls.');
if (requestedDryRun) gateReasons.push('DRY_RUN=true — no writes to HubSpot.');
if (!creationEnabled) gateReasons.push('RENEWAL_DEALS_CREATION_ENABLED=false — renewal deals are previewed only.');

const slackAlertsPermitted = sendSlackAlerts && !sandboxMode && hasSlackWebhook;
const webhookAlertsPermitted = sendWebhookAlerts && !sandboxMode && hasAlertWebhook;

// ---- Live search bodies (non-secret) -------------------------------
const DAY = 86400000;
const refMs = Date.parse(`${referenceDate}T00:00:00Z`);
const searchHorizonDays = radar.provisionWithinDays + 1;
const dealProps = ['dealname', 'pipeline', 'dealstage', 'amount', 'closedate', 'hubspot_owner_id', hubspot.props.contractEndDate, hubspot.props.arr, hubspot.props.lastMilestone];
const live = {
  searchExpiringBody: {
    filterGroups: [{
      filters: [
        { propertyName: hubspot.props.contractEndDate, operator: 'BETWEEN', value: String(refMs), highValue: String(refMs + searchHorizonDays * DAY) },
        { propertyName: 'pipeline', operator: 'EQ', value: hubspot.sourcePipelineId },
        { propertyName: 'dealstage', operator: 'IN', values: hubspot.sourceWonStageIds },
      ],
    }],
    properties: [...new Set(dealProps)],
    sorts: [{ propertyName: hubspot.props.contractEndDate, direction: 'ASCENDING' }],
    limit: 100,
  },
  searchRenewalsBody: {
    filterGroups: [{
      filters: [
        { propertyName: 'pipeline', operator: 'EQ', value: hubspot.renewalPipelineId },
        { propertyName: 'closedate', operator: 'GTE', value: String(refMs - 30 * DAY) },
      ],
    }],
    properties: ['dealname', 'pipeline', 'dealstage', 'amount', 'closedate', 'hubspot_owner_id', hubspot.props.contractEndDate, hubspot.props.renewalSourceDealId, hubspot.props.renewalKey],
    limit: 100,
  },
  companyProperties: ['name', 'domain', hubspot.props.companyTier],
};

// ---- Run metadata --------------------------------------------------
const startedAt = new Date().toISOString();
let trigger = 'manual';
try { if ($('Daily 08:00 UTC Schedule').isExecuted) trigger = 'schedule'; } catch (e) { /* manual */ }
const runId = `renewal-radar-${startedAt.slice(0, 10).replace(/-/g, '')}-${Math.random().toString(36).slice(2, 8)}`;
const anyWrite = Object.values(permissions).some(Boolean);
const mode = sandboxMode ? 'SANDBOX' : anyWrite ? 'LIVE' : 'DRY_RUN';

return [{
  json: {
    runId,
    startedAt,
    trigger,
    workflow: 'n8n-renewal-forecast-contract-expiration-radar',
    workflowVersion: '1.0.0',
    config: { hubspot, radar, limits, alerts, live },
    gate: {
      mode,
      sandboxMode,
      dryRun,
      requested: { sandboxMode: requestedSandbox, dryRun: requestedDryRun, creationEnabled, stageUpdatesEnabled, writebackEnabled, sendSlackAlerts, sendWebhookAlerts },
      permissions,
      mappingExplicit,
      slackAlertsPermitted,
      webhookAlertsPermitted,
      secretsPresent: { hubspotAccessToken: hasHubspotToken, slackWebhook: hasSlackWebhook, alertWebhook: hasAlertWebhook },
      envAccessBlocked,
      reasons: gateReasons,
      warnings: gateWarnings,
      configErrors,
    },
  },
}];

