// =====================================================================
// Renewal Radar & Deal Provisioning Engine
// 1. Normalizes HubSpot deals, companies, associations and owners.
// 2. Finds enterprise contracts hitting the 90/60/30-day milestones.
// 3. Prevents duplicate renewal deals (source ID, idempotency key,
//    company association match, and in-run dedupe).
// 4. Builds HubSpot batch payloads: create renewal deals, advance
//    renewal stages, write back the last milestone alerted.
// 5. Applies guardrails: per-run cap, circuit breaker, permissions.
// =====================================================================
const ctx = $input.first().json;
const { config: cfg, gate } = ctx;
const H = cfg.hubspot;
const R = cfg.radar;
const L = cfg.limits;
const P = H.props;
const raw = ctx.raw || {};
const DAY = 86400000;

const results = (obj) => (obj && Array.isArray(obj.results) ? obj.results : []);
const num = (v) => { const x = Number(v); return v === null || v === undefined || v === '' || !Number.isFinite(x) ? null : x; };
const round2 = (v) => Math.round(v * 100) / 100;

// Accepts YYYY-MM-DD, ISO date-time, or epoch milliseconds. Returns YYYY-MM-DD (UTC) or null.
function parseDate(v) {
  if (v === null || v === undefined || v === '') return null;
  const s = String(v).trim();
  let ms = NaN;
  if (/^\d{10,14}$/.test(s)) ms = Number(s);
  else if (/^\d{4}-\d{2}-\d{2}$/.test(s)) ms = Date.parse(`${s}T00:00:00Z`);
  else ms = Date.parse(s);
  if (!Number.isFinite(ms)) return null;
  return new Date(ms).toISOString().slice(0, 10);
}
const refDate = R.referenceDate;
const refMs = Date.parse(`${refDate}T00:00:00Z`);
const daysUntil = (d) => Math.round((Date.parse(`${d}T00:00:00Z`) - refMs) / DAY);
const daysBetween = (a, b) => Math.abs(Math.round((Date.parse(`${a}T00:00:00Z`) - Date.parse(`${b}T00:00:00Z`)) / DAY));

// ---------------------------------------------------------------------
// 1. Normalize
// ---------------------------------------------------------------------
const assocByDeal = {};
for (const a of results(raw.deal_company_associations)) {
  const from = String(a.from && a.from.id);
  const tos = (a.to || []);
  const primary = tos.find((t) => (t.associationTypes || []).some((x) => Number(x.typeId) === Number(H.associationTypeId)));
  const ordered = primary ? [primary, ...tos.filter((t) => t !== primary)] : tos;
  assocByDeal[from] = [...new Set(ordered.map((t) => String(t.toObjectId)))];
}
const companies = Object.fromEntries(results(raw.companies_batch_read).map((c) => [String(c.id), {
  company_id: String(c.id),
  name: (c.properties && c.properties.name) || `Company ${c.id}`,
  domain: (c.properties && c.properties.domain) || null,
  tier: (c.properties && c.properties[P.companyTier]) || null,
}]));
const owners = Object.fromEntries(results(raw.owners).map((o) => [String(o.id), {
  owner_id: String(o.id),
  name: [o.firstName, o.lastName].filter(Boolean).join(' ') || `Owner ${o.id}`,
  active: !o.archived,
}]));

const sourceDeals = results(raw.deals_search_results).map((d) => {
  const p = d.properties || {};
  return {
    deal_id: String(d.id),
    dealname: p.dealname || `Deal ${d.id}`,
    pipeline: p.pipeline || null,
    dealstage: p.dealstage || null,
    contract_end_raw: p[P.contractEndDate] ?? null,
    contract_end_date: parseDate(p[P.contractEndDate]),
    arr: num(p[P.arr]) ?? num(p.amount),
    owner_id: p.hubspot_owner_id ? String(p.hubspot_owner_id) : null,
    last_milestone: num(p[P.lastMilestone]),
    company_ids: assocByDeal[String(d.id)] || [],
  };
});

const renewalDeals = results(raw.renewal_deals_search_results).map((d) => {
  const p = d.properties || {};
  return {
    deal_id: String(d.id),
    dealname: p.dealname || `Deal ${d.id}`,
    pipeline: p.pipeline || null,
    dealstage: p.dealstage || null,
    closedate: parseDate(p.closedate),
    contract_end_date: parseDate(p[P.contractEndDate]),
    source_deal_id: p[P.renewalSourceDealId] ? String(p[P.renewalSourceDealId]) : null,
    renewal_key: p[P.renewalKey] || null,
    owner_id: p.hubspot_owner_id ? String(p.hubspot_owner_id) : null,
    company_ids: assocByDeal[String(d.id)] || [],
    is_closed: H.renewalClosedStageIds.includes(p.dealstage),
  };
}).filter((r) => r.pipeline === H.renewalPipelineId);

const renewalBySource = {};
const renewalByKey = {};
for (const r of renewalDeals) {
  if (r.source_deal_id) renewalBySource[r.source_deal_id] = r;
  if (r.renewal_key) renewalByKey[r.renewal_key] = r;
}
const claimedRenewalIds = new Set(renewalDeals.filter((r) => r.source_deal_id || r.renewal_key).map((r) => r.deal_id));

// ---------------------------------------------------------------------
// 2. Evaluate each contract
// ---------------------------------------------------------------------
const windowsAsc = [...R.windows].sort((a, b) => a - b);
const stageOrder = [...R.windows].sort((a, b) => b - a).map((w) => H.stageMap[w]);
const targetStageFor = (days) => { const w = windowsAsc.find((x) => days <= x); return w ? H.stageMap[w] : null; };
const fill = (tpl, vars) => tpl.replace(/\{(\w+)\}/g, (m, k) => (vars[k] !== undefined && vars[k] !== null ? String(vars[k]) : m));
const seenKeys = new Set();
const dataQuality = [];

const contracts = sourceDeals.map((d) => {
  const company = companies[d.company_ids[0]] || null;
  const base = {
    deal_id: d.deal_id,
    dealname: d.dealname,
    company_id: company ? company.company_id : (d.company_ids[0] || null),
    company_name: company ? company.name : null,
    company_tier: company ? company.tier : null,
    arr: d.arr,
    contract_end_date: d.contract_end_date,
    owner_id: d.owner_id,
    notes: [],
  };

  if (!H.sourceWonStageIds.includes(d.dealstage) || d.pipeline !== H.sourcePipelineId) {
    return { ...base, status: 'SKIPPED_NOT_CLOSED_WON', days_until_expiration: null, milestone: null };
  }
  if (!d.contract_end_date) {
    dataQuality.push({ deal_id: d.deal_id, issue: `Unparseable ${P.contractEndDate} value "${d.contract_end_raw}"` });
    return { ...base, status: 'DATA_QUALITY_INVALID_DATE', days_until_expiration: null, milestone: null, notes: [`Contract end date "${d.contract_end_raw}" could not be parsed`] };
  }
  const days = daysUntil(d.contract_end_date);
  base.days_until_expiration = days;

  const tierOk = company && company.tier && R.enterpriseTierValues.includes(String(company.tier).toLowerCase());
  const arrOk = d.arr !== null && d.arr >= R.enterpriseMinArr;
  if (!tierOk && !arrOk) return { ...base, status: 'SKIPPED_NOT_ENTERPRISE', milestone: null, notes: [`Tier "${base.company_tier || 'n/a'}" and ARR ${d.arr ?? 'n/a'} are below the enterprise threshold`] };
  if (d.arr === null) { dataQuality.push({ deal_id: d.deal_id, issue: `Missing ${P.arr} and amount` }); base.notes.push('ARR missing — renewal amount left blank'); }
  if (days < 0) return { ...base, status: 'EXPIRED', milestone: null, notes: ['Contract already expired — outside radar scope'] };
  if (days > R.provisionWithinDays) return { ...base, status: 'OUTSIDE_RADAR', milestone: null };
  if (!company) { dataQuality.push({ deal_id: d.deal_id, issue: 'No associated company' }); base.notes.push('No associated company — renewal deal will not be associated'); }

  // Milestone hit (exact day, or within catch-up tolerance if write-back keeps state)
  let milestone = null; let catchup = false;
  for (const w of windowsAsc) {
    if (days <= w && days >= w - R.catchupDays && (d.last_milestone === null || d.last_milestone > w)) { milestone = w; catchup = days !== w; break; }
  }
  if (!milestone && d.last_milestone !== null && windowsAsc.includes(days) && d.last_milestone <= days) base.notes.push(`Milestone ${days}d already alerted`);

  // Owner mapping
  let ownerId = d.owner_id; let ownerNote = null;
  if (!ownerId || !owners[ownerId] || !owners[ownerId].active) {
    ownerNote = !ownerId ? 'Source deal has no owner' : `Owner ${ownerId} is inactive or not found`;
    ownerId = H.fallbackOwnerId && owners[H.fallbackOwnerId] && owners[H.fallbackOwnerId].active ? H.fallbackOwnerId : null;
    base.notes.push(`${ownerNote} — ${ownerId ? `assigned fallback owner ${ownerId}` : 'renewal left unassigned'}`);
  }
  const owner = ownerId ? owners[ownerId] : null;

  // Duplicate prevention
  const key = `renewal-${d.deal_id}-${d.contract_end_date}`;
  let existing = null; let dupReason = null;
  if (renewalBySource[d.deal_id]) { existing = renewalBySource[d.deal_id]; dupReason = `${P.renewalSourceDealId} match`; }
  else if (renewalByKey[key]) { existing = renewalByKey[key]; dupReason = `${P.renewalKey} match`; }
  else if (base.company_id) {
    existing = renewalDeals.find((r) => !r.is_closed && !claimedRenewalIds.has(r.deal_id) && r.company_ids.includes(base.company_id)
      && (r.contract_end_date || r.closedate) && daysBetween(r.contract_end_date || r.closedate, d.contract_end_date) <= R.associationMatchToleranceDays) || null;
    if (existing) { dupReason = `open renewal deal on company ${base.company_id} closing within ${R.associationMatchToleranceDays}d`; claimedRenewalIds.add(existing.deal_id); }
  }
  if (!existing && seenKeys.has(key)) { dupReason = 'duplicate within this run'; }

  const targetStage = targetStageFor(days);
  const result = {
    ...base,
    milestone,
    milestone_catchup: catchup,
    idempotency_key: key,
    target_stage: targetStage,
    renewal_owner_id: ownerId,
    renewal_owner_name: owner ? owner.name : null,
    owner_fallback_used: Boolean(ownerNote),
    existing_renewal: existing ? { deal_id: existing.deal_id, dealstage: existing.dealstage, matched_by: dupReason, is_closed: existing.is_closed } : null,
  };

  if (existing || dupReason) {
    result.status = 'RENEWAL_EXISTS';
    result.duplicate_prevented = dupReason;
    if (dupReason && dupReason.startsWith('open renewal')) result.notes.push(`Matched existing renewal ${existing.deal_id} by association — review and set ${P.renewalSourceDealId}=${d.deal_id} on it`);
    // Stage advancement: forward only, mapped stages only, never closed deals
    if (existing && !existing.is_closed && targetStage) {
      const cur = stageOrder.indexOf(existing.dealstage);
      const tgt = stageOrder.indexOf(targetStage);
      if (cur >= 0 && tgt > cur) result.stage_update = { deal_id: existing.deal_id, from: existing.dealstage, to: targetStage };
      else if (cur < 0) result.notes.push(`Renewal ${existing.deal_id} is in unmapped stage "${existing.dealstage}" — stage left untouched`);
    }
    return result;
  }

  seenKeys.add(key);
  const vars = { company_name: base.company_name || d.dealname, source_deal_name: d.dealname, contract_end_date: d.contract_end_date, contract_end_year: d.contract_end_date.slice(0, 4) };
  const amount = d.arr !== null ? round2(d.arr * (1 + R.upliftPct / 100)) : null;
  const properties = {
    dealname: fill(R.dealNameTemplate, vars).slice(0, 250),
    pipeline: H.renewalPipelineId,
    dealstage: targetStage,
    closedate: `${d.contract_end_date}T00:00:00.000Z`,
    [P.contractEndDate]: d.contract_end_date,
    [P.renewalSourceDealId]: d.deal_id,
    [P.renewalKey]: key,
  };
  if (amount !== null) { properties.amount = String(amount); properties[P.arr] = String(d.arr); }
  if (ownerId) properties.hubspot_owner_id = ownerId;
  result.status = 'PROVISION';
  result.provision_reason = milestone ? `Milestone ${milestone}d${catchup ? ' (catch-up)' : ''}` : `Backfill: no renewal deal within ${R.provisionWithinDays}d of expiration`;
  result.create_input = {
    properties,
    associations: base.company_id && company ? [{ to: { id: base.company_id }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: H.associationTypeId }] }] : [],
  };
  return result;
});

// ---------------------------------------------------------------------
// 3. Guardrails
// ---------------------------------------------------------------------
const provisions = contracts.filter((c) => c.status === 'PROVISION').sort((a, b) => a.days_until_expiration - b.days_until_expiration || (b.arr || 0) - (a.arr || 0));
const datedTotal = contracts.filter((c) => c.status !== 'SKIPPED_NOT_CLOSED_WON').length;
const invalidPct = datedTotal ? (dataQuality.filter((q) => q.issue.startsWith('Unparseable')).length / datedTotal) * 100 : 0;
const cbReasons = [];
if (provisions.length > L.circuitBreakerMaxProposed) cbReasons.push(`${provisions.length} renewal deals proposed (breaker at ${L.circuitBreakerMaxProposed}) — check ${P.contractEndDate} mapping`);
if (datedTotal >= 5 && invalidPct >= L.circuitBreakerInvalidDatePct) cbReasons.push(`${Math.round(invalidPct)}% of contracts have invalid end dates (breaker at ${L.circuitBreakerInvalidDatePct}%)`);
const circuitBreaker = { tripped: cbReasons.length > 0, reasons: cbReasons, proposed_creates: provisions.length, invalid_date_pct: Math.round(invalidPct * 10) / 10 };

provisions.forEach((c, i) => {
  if (circuitBreaker.tripped) { c.status = 'BLOCKED_CIRCUIT_BREAKER'; c.notes.push('Circuit breaker tripped — creation held'); }
  else if (i >= L.maxRenewalDealsPerRun) { c.status = 'DEFERRED_RATE_LIMIT'; c.notes.push(`Per-run cap of ${L.maxRenewalDealsPerRun} reached — will be created on a later run`); }
});

// ---------------------------------------------------------------------
// 4. HubSpot batch operations
// ---------------------------------------------------------------------
const chunk = (arr, n) => { const out = []; for (let i = 0; i < arr.length; i += n) out.push(arr.slice(i, i + n)); return out; };
const blockedBy = (permKey) => {
  if (gate.sandboxMode) return 'SANDBOX_MODE';
  if (circuitBreaker.tripped) return 'CIRCUIT_BREAKER';
  if (gate.requested.dryRun) return 'DRY_RUN';
  if (gate.configErrors.length) return 'CONFIG_INVALID';
  if (!gate.mappingExplicit) return 'MAPPING_NOT_CONFIGURED';
  if (!gate.permissions[permKey]) return { createRenewalDeals: 'CREATION_DISABLED', updateRenewalStages: 'STAGE_UPDATES_DISABLED', milestoneWriteback: 'WRITEBACK_DISABLED' }[permKey];
  return null;
};
const operations = [];
const toCreate = contracts.filter((c) => c.status === 'PROVISION');
chunk(toCreate, L.batchSize).forEach((group, i) => operations.push({
  op_id: `create-${i + 1}`, kind: 'CREATE_RENEWAL_DEALS', method: 'POST', path: '/crm/v3/objects/deals/batch/create',
  record_count: group.length, keys: group.map((c) => c.idempotency_key), source_deal_ids: group.map((c) => c.deal_id),
  body: { inputs: group.map((c) => c.create_input) }, blocked_reason: blockedBy('createRenewalDeals'),
}));
const stageUpdates = circuitBreaker.tripped ? [] : contracts.filter((c) => c.stage_update).map((c) => c.stage_update);
chunk(stageUpdates, L.batchSize).forEach((group, i) => operations.push({
  op_id: `stage-${i + 1}`, kind: 'UPDATE_RENEWAL_STAGES', method: 'POST', path: '/crm/v3/objects/deals/batch/update',
  record_count: group.length, deal_ids: group.map((g) => g.deal_id),
  body: { inputs: group.map((g) => ({ id: g.deal_id, properties: { dealstage: g.to } })) }, blocked_reason: blockedBy('updateRenewalStages'),
}));
const milestoneHits = contracts.filter((c) => c.milestone);
chunk(milestoneHits, L.batchSize).forEach((group, i) => operations.push({
  op_id: `milestone-${i + 1}`, kind: 'WRITEBACK_MILESTONES', method: 'POST', path: '/crm/v3/objects/deals/batch/update',
  record_count: group.length, deal_ids: group.map((c) => c.deal_id),
  body: { inputs: group.map((c) => ({ id: c.deal_id, properties: { [P.lastMilestone]: String(c.milestone) } })) }, blocked_reason: blockedBy('milestoneWriteback'),
}));
operations.forEach((o) => { o.url = `${H.apiBaseUrl}${o.path}`; o.permitted = o.blocked_reason === null; });

// ---------------------------------------------------------------------
// 5. Forecast & stats
// ---------------------------------------------------------------------
const inRadar = contracts.filter((c) => c.days_until_expiration !== null && c.days_until_expiration >= 0 && c.days_until_expiration <= R.provisionWithinDays && !['SKIPPED_NOT_ENTERPRISE', 'SKIPPED_NOT_CLOSED_WON', 'DATA_QUALITY_INVALID_DATE'].includes(c.status));
const bucketOf = (d) => windowsAsc.find((w) => d <= w);
const forecast = windowsAsc.map((w) => {
  const rows = inRadar.filter((c) => bucketOf(c.days_until_expiration) === w);
  return { window_days: w, contracts: rows.length, arr_at_risk: round2(rows.reduce((a, c) => a + (c.arr || 0), 0)), without_renewal_deal: rows.filter((c) => !c.existing_renewal).length };
});
const stats = {
  contracts_scanned: contracts.length,
  enterprise_in_radar: inRadar.length,
  milestone_hits: milestoneHits.length,
  milestone_hits_by_window: Object.fromEntries(windowsAsc.map((w) => [w, milestoneHits.filter((c) => c.milestone === w).length])),
  renewal_deals_to_create: toCreate.length,
  renewal_deals_deferred: contracts.filter((c) => c.status === 'DEFERRED_RATE_LIMIT').length,
  renewal_deals_blocked: contracts.filter((c) => c.status === 'BLOCKED_CIRCUIT_BREAKER').length,
  duplicates_prevented: contracts.filter((c) => c.status === 'RENEWAL_EXISTS').length,
  stage_advances_proposed: stageUpdates.length,
  skipped_not_enterprise: contracts.filter((c) => c.status === 'SKIPPED_NOT_ENTERPRISE').length,
  outside_radar: contracts.filter((c) => c.status === 'OUTSIDE_RADAR').length,
  data_quality_issues: dataQuality.length,
  total_arr_in_radar: round2(inRadar.reduce((a, c) => a + (c.arr || 0), 0)),
  arr_without_renewal_deal: round2(inRadar.filter((c) => !c.existing_renewal).reduce((a, c) => a + (c.arr || 0), 0)),
};

return [{
  json: {
    runId: ctx.runId, startedAt: ctx.startedAt, trigger: ctx.trigger, workflow: ctx.workflow, workflowVersion: ctx.workflowVersion,
    dataSource: ctx.dataSource,
    referenceDate: refDate,
    config: cfg,
    gate,
    circuitBreaker,
    stats,
    forecast,
    contracts: contracts.map(({ create_input, ...rest }) => ({ ...rest, has_create_payload: Boolean(create_input) })),
    dataQuality,
    fetchWarnings: raw.fetch_warnings || [],
    operations,
    liveWriteAllowed: operations.some((o) => o.permitted),
    evaluatedAt: new Date().toISOString(),
  },
}];

// =====================================================================
// Split HubSpot Operations (live branch only)
// Second, independent safety interlock. Re-checks the gate and emits one
// item per PERMITTED batch operation, creates first.
// =====================================================================
const plan = $input.first().json;
const g = plan.gate;
if (!(plan.liveWriteAllowed === true && g.sandboxMode === false && g.dryRun === false && g.requested.dryRun === false && g.mappingExplicit === true && plan.circuitBreaker.tripped === false)) {
  throw new Error('Safety interlock: HubSpot write branch reached without full authorization. No requests were sent.');
}
const permKey = { CREATE_RENEWAL_DEALS: 'createRenewalDeals', UPDATE_RENEWAL_STAGES: 'updateRenewalStages', WRITEBACK_MILESTONES: 'milestoneWriteback' };
const order = { CREATE_RENEWAL_DEALS: 0, UPDATE_RENEWAL_STAGES: 1, WRITEBACK_MILESTONES: 2 };

return plan.operations
  .filter((o) => o.permitted && g.permissions[permKey[o.kind]] === true)
  .sort((a, b) => order[a.kind] - order[b.kind])
  .map((o) => ({ json: { op_id: o.op_id, kind: o.kind, url: o.url, body: o.body, record_count: o.record_count } }));

// =====================================================================
// Collect HubSpot Results (live branch)
// Pairs each batch response with its operation. Handles 200/201 (all
// succeeded), 207 (partial) and errors. Maps created renewal deal IDs
// back to source contracts via the idempotency key property.
// =====================================================================
const plan = $('Renewal Radar & Provisioning Engine').first().json;
const sent = $('Split HubSpot Operations').all();
const responses = $input.all();
const keyProp = plan.config.hubspot.props.renewalKey;

const opResults = responses.map((r, i) => {
  const idx = r.pairedItem && typeof r.pairedItem.item === 'number' ? r.pairedItem.item : i;
  const req = (sent[idx] || sent[i] || { json: {} }).json;
  const j = r.json || {};
  const status = Number(j.statusCode);
  const body = j.body || {};
  const ok = !j.error && status >= 200 && status < 300;
  const created = (body.results || []).map((x) => ({ deal_id: String(x.id), idempotency_key: x.properties ? x.properties[keyProp] : null }));
  const errors = (body.errors || []).map((e) => String(e.message || e.category || 'error').slice(0, 200));
  return {
    op_id: req.op_id,
    kind: req.kind,
    record_count: req.record_count,
    status: !ok ? 'FAILED' : status === 207 || errors.length ? 'PARTIAL' : 'APPLIED',
    http_status: Number.isFinite(status) ? status : null,
    succeeded: (body.results || []).length,
    errors: j.error ? [String(j.error.message || j.error).slice(0, 300)] : errors,
    created,
  };
});

const createdByKey = Object.fromEntries(opResults.flatMap((o) => o.created).filter((c) => c.idempotency_key).map((c) => [c.idempotency_key, c.deal_id]));
const executedIds = new Set(opResults.map((o) => o.op_id));
for (const o of plan.operations) if (!executedIds.has(o.op_id)) opResults.push({ op_id: o.op_id, kind: o.kind, record_count: o.record_count, status: o.blocked_reason ? `BLOCKED_${o.blocked_reason}` : 'NOT_SENT', http_status: null, succeeded: 0, errors: [], created: [] });

return [{
  json: {
    ...plan,
    writeResults: opResults,
    createdRenewals: createdByKey,
    writeSummary: {
      mode: 'LIVE',
      deals_created: Object.keys(createdByKey).length,
      operations_applied: opResults.filter((o) => o.status === 'APPLIED').length,
      operations_partial: opResults.filter((o) => o.status === 'PARTIAL').length,
      operations_failed: opResults.filter((o) => o.status === 'FAILED').length,
      operations_previewed: 0,
    },
  },
}];

// =====================================================================
// Dry-Run HubSpot Preview
// Records exactly what WOULD be sent to HubSpot. No external calls.
// =====================================================================
const plan = $input.first().json;
const g = plan.gate;
let mode = 'DRY_RUN_PREVIEW';
if (g.sandboxMode) mode = 'SANDBOX_PREVIEW';
else if (plan.circuitBreaker.tripped) mode = 'BLOCKED_CIRCUIT_BREAKER';
else if (g.configErrors.length) mode = 'BLOCKED_CONFIG_INVALID';
else if (!plan.operations.length) mode = 'NOTHING_TO_WRITE';

const writeResults = plan.operations.map((o) => ({
  op_id: o.op_id,
  kind: o.kind,
  record_count: o.record_count,
  status: `PREVIEW_${o.blocked_reason || 'NOT_SENT'}`,
  http_status: null,
  succeeded: 0,
  errors: [],
  created: [],
  would_send: { method: o.method, url: o.url, body: o.body },
}));

return [{
  json: {
    ...plan,
    writeResults,
    createdRenewals: {},
    writeSummary: { mode, deals_created: 0, operations_applied: 0, operations_partial: 0, operations_failed: 0, operations_previewed: writeResults.length },
  },
}];

// =====================================================================
// Build RevOps Alerts
// Slack Block Kit message grouped by Account Manager, plus a compact JSON
// webhook event. Uses HubSpot record IDs, company names, owner names and
// ARR only — no contact-level personal data.
// =====================================================================
const run = $input.first().json;
const { gate, circuitBreaker: cb, stats, config: cfg, forecast } = run;
const maxItems = cfg.alerts.maxItemsPerSection;
const portal = cfg.hubspot.portalId;
const SEV = { INFO: 0, WARNING: 1, CRITICAL: 2 };

let fmt;
try { fmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: cfg.radar.currency, maximumFractionDigits: 0 }); } catch (e) { fmt = new Intl.NumberFormat('en-US', { maximumFractionDigits: 0 }); }
const money = (v) => (v === null || v === undefined ? 'n/a' : fmt.format(v));
const dealUrl = (id) => `https://app.hubspot.com/contacts/${encodeURIComponent(portal)}/record/0-3/${encodeURIComponent(id)}`;
const link = (id, label) => `<${dealUrl(id)}|${label}>`;
const truncate = (s, max = 2900) => (s.length > max ? `${s.slice(0, max - 20)}\n_…truncated_` : s);
const urgency = (d) => (d <= 30 ? ':red_circle:' : d <= 60 ? ':large_orange_circle:' : ':large_yellow_circle:');

const createdByKey = run.createdRenewals || {};
const mode = run.writeSummary.mode;
const actionable = run.contracts.filter((c) => c.milestone || ['PROVISION', 'DEFERRED_RATE_LIMIT', 'BLOCKED_CIRCUIT_BREAKER'].includes(c.status) || (c.status === 'RENEWAL_EXISTS' && c.days_until_expiration !== null && c.days_until_expiration <= cfg.radar.provisionWithinDays && (c.milestone || String(c.duplicate_prevented || '').startsWith('open renewal'))));

const renewalLabel = (c) => {
  if (c.status === 'PROVISION') {
    const id = createdByKey[c.idempotency_key];
    if (id) return `:new: renewal ${link(id, `#${id}`)} created`;
    return mode === 'LIVE' ? ':x: renewal creation not confirmed' : `:memo: renewal deal ${mode === 'SANDBOX_PREVIEW' ? 'previewed (sandbox)' : 'previewed'}`;
  }
  if (c.status === 'RENEWAL_EXISTS' && c.existing_renewal) {
    const stage = c.stage_update ? ` · stage → \`${c.stage_update.to}\`${run.gate.permissions.updateRenewalStages && mode === 'LIVE' ? '' : ' (proposed)'}` : '';
    return `:white_check_mark: renewal ${link(c.existing_renewal.deal_id, `#${c.existing_renewal.deal_id}`)} exists (${c.existing_renewal.matched_by})${stage}`;
  }
  if (c.status === 'DEFERRED_RATE_LIMIT') return ':hourglass: creation deferred (per-run cap)';
  if (c.status === 'BLOCKED_CIRCUIT_BREAKER') return ':octagonal_sign: creation blocked (circuit breaker)';
  return `status ${c.status}`;
};

let severity = 'INFO';
if (actionable.length || run.dataQuality.length) severity = 'WARNING';
const thirtyNoRenewal = actionable.some((c) => c.days_until_expiration <= 30 && !c.existing_renewal && !createdByKey[c.idempotency_key]);
if (cb.tripped || thirtyNoRenewal || run.writeSummary.operations_failed > 0 || run.writeSummary.operations_partial > 0) severity = 'CRITICAL';

const modeLabel = {
  LIVE: ':satellite_antenna: LIVE', SANDBOX_PREVIEW: ':test_tube: SANDBOX (mock data)', DRY_RUN_PREVIEW: ':eyes: DRY RUN',
  BLOCKED_CIRCUIT_BREAKER: ':octagonal_sign: BLOCKED (circuit breaker)', BLOCKED_CONFIG_INVALID: ':no_entry: BLOCKED (invalid config)', NOTHING_TO_WRITE: ':white_check_mark: NOTHING TO WRITE',
}[mode] || mode;
const header = { INFO: ':calendar: Renewal Radar — No Milestones Today', WARNING: ':calendar: Renewal Radar — Contracts Hitting Renewal Milestones', CRITICAL: ':rotating_light: Renewal Radar — Urgent Renewals Need Attention' }[severity];

const blocks = [];
blocks.push({ type: 'header', text: { type: 'plain_text', text: header, emoji: true } });
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `*Run* \`${run.runId}\`  ·  *Mode* ${modeLabel}  ·  *Source* ${run.dataSource}  ·  *Radar date* ${run.referenceDate}  ·  *Windows* ${cfg.radar.windows.join('/')}d` }] });
if (cb.tripped) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: truncate(`:octagonal_sign: *CIRCUIT BREAKER TRIPPED — no renewal deals were created*\n${cb.reasons.map((r) => `• ${r}`).join('\n')}`) } });

blocks.push({
  type: 'section',
  fields: [
    { type: 'mrkdwn', text: `*Enterprise contracts in radar*\n${stats.enterprise_in_radar} (≤${cfg.radar.provisionWithinDays}d)` },
    { type: 'mrkdwn', text: `*ARR up for renewal*\n${money(stats.total_arr_in_radar)}` },
    { type: 'mrkdwn', text: `*ARR without a renewal deal*\n${money(stats.arr_without_renewal_deal)}` },
    { type: 'mrkdwn', text: `*Milestone hits today*\n${cfg.radar.windows.map((w) => `${w}d: ${stats.milestone_hits_by_window[w] || 0}`).join(' · ')}` },
    { type: 'mrkdwn', text: `*Renewal deals*\n${run.writeSummary.deals_created} created · ${stats.renewal_deals_to_create} ${mode === 'LIVE' ? 'queued' : 'previewed'}` },
    { type: 'mrkdwn', text: `*Duplicates prevented*\n${stats.duplicates_prevented}` },
  ],
});

blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*:bar_chart: Renewal forecast by window*\n${forecast.map((f) => `• ≤${f.window_days}d — ${f.contracts} contract(s) · ${money(f.arr_at_risk)} ARR · ${f.without_renewal_deal} without renewal deal`).join('\n')}` } });
blocks.push({ type: 'divider' });

const byOwner = {};
for (const c of actionable) {
  const key = c.renewal_owner_id || 'unassigned';
  (byOwner[key] = byOwner[key] || { name: c.renewal_owner_name || 'Unassigned', rows: [] }).rows.push(c);
}
const ownerKeys = Object.keys(byOwner).sort((a, b) => Math.min(...byOwner[a].rows.map((r) => r.days_until_expiration)) - Math.min(...byOwner[b].rows.map((r) => r.days_until_expiration)));
if (!ownerKeys.length) {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '*:busts_in_silhouette: Account Managers*\nNo contracts need action today.' } });
} else {
  for (const k of ownerKeys.slice(0, 20)) {
    const grp = byOwner[k];
    const arr = grp.rows.reduce((a, c) => a + (c.arr || 0), 0);
    const rows = grp.rows.sort((a, b) => a.days_until_expiration - b.days_until_expiration).slice(0, maxItems).map((c) => {
      const tag = c.milestone ? `*${c.milestone}-day milestone*${c.milestone_catchup ? ' (catch-up)' : ''}` : `${c.days_until_expiration}d out`;
      const extra = c.owner_fallback_used ? '\n      :warning: original owner inactive or missing — fallback owner assigned' : '';
      return `${urgency(c.days_until_expiration)} ${link(c.deal_id, c.company_name || c.dealname)} — ${tag} · ends ${c.contract_end_date} · ${money(c.arr)} ARR\n      ${renewalLabel(c)}${extra}`;
    });
    if (grp.rows.length > maxItems) rows.push(`_+${grp.rows.length - maxItems} more in the audit log_`);
    blocks.push({ type: 'section', text: { type: 'mrkdwn', text: truncate(`*:bust_in_silhouette: ${grp.name}*${k !== 'unassigned' ? ` (owner \`${k}\`)` : ''} — ${grp.rows.length} contract(s) · ${money(arr)} ARR\n${rows.join('\n')}`) } });
  }
}

if (run.dataQuality.length) {
  blocks.push({ type: 'divider' });
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: truncate(`*:mag: Data quality*\n${run.dataQuality.slice(0, maxItems).map((q) => `• Deal ${link(q.deal_id, `#${q.deal_id}`)}: ${q.issue}`).join('\n')}`) } });
}

const footer = mode === 'LIVE' ? 'Changes were written to HubSpot. Review the audit log for per-batch results.' : 'Preview only — nothing was written to HubSpot.';
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `${footer}  ·  n8n-renewal-forecast-contract-expiration-radar v${run.workflowVersion}` }] });

const meets = SEV[severity] >= SEV[cfg.alerts.minSeverity];
const dispatch = { severity, meetsMinSeverity: meets, slack: gate.slackAlertsPermitted === true && meets, webhook: gate.webhookAlertsPermitted === true && meets };

const webhookEvent = {
  event: 'crm.renewal_radar.run_completed',
  run_id: run.runId,
  severity,
  mode,
  data_source: run.dataSource,
  radar_date: run.referenceDate,
  circuit_breaker: { tripped: cb.tripped, reasons: cb.reasons },
  stats,
  forecast,
  write_summary: run.writeSummary,
  contracts: actionable.map((c) => ({
    source_deal_id: c.deal_id, company_id: c.company_id, days_until_expiration: c.days_until_expiration, contract_end_date: c.contract_end_date,
    arr: c.arr, milestone: c.milestone, status: c.status, owner_id: c.renewal_owner_id,
    renewal_deal_id: (c.existing_renewal && c.existing_renewal.deal_id) || createdByKey[c.idempotency_key] || null,
  })),
};

return [{
  json: {
    ...run,
    alerts: { dispatch, slackPayload: { text: `[${severity}] Renewal radar ${run.runId}: ${actionable.length} contract(s) need action, ${money(stats.arr_without_renewal_deal)} ARR without a renewal deal. Mode ${mode}.`, blocks: blocks.slice(0, 50) }, webhookEvent },
  },
}];

// =====================================================================
// Execution Summary & Audit
// One structured audit record per run. Send it to your log store,
// warehouse or a HubSpot custom object for a durable trail.
// =====================================================================
const run = $('Build RevOps Alerts').first().json;
const dispatchStatus = (nodeName, wanted) => {
  if (!wanted) return 'NOT_SENT';
  try {
    if (!$(nodeName).isExecuted) return 'NOT_SENT';
    const j = $(nodeName).first().json || {};
    return j.error ? `FAILED: ${String(j.error.message || j.error).slice(0, 200)}` : 'SENT';
  } catch (e) { return 'UNKNOWN'; }
};
const finishedAt = new Date().toISOString();

return [{
  json: {
    audit: {
      run_id: run.runId,
      workflow: run.workflow,
      workflow_version: run.workflowVersion,
      trigger: run.trigger,
      started_at: run.startedAt,
      finished_at: finishedAt,
      duration_ms: Date.parse(finishedAt) - Date.parse(run.startedAt),
      data_source: run.dataSource,
      radar_reference_date: run.referenceDate,
      radar_reference_date_source: run.config.radar.referenceDateSource,
      safety: {
        mode: run.gate.mode,
        sandbox_mode: run.gate.sandboxMode,
        dry_run: run.gate.dryRun,
        permissions: run.gate.permissions,
        mapping_explicit: run.gate.mappingExplicit,
        write_mode: run.writeSummary.mode,
        circuit_breaker: run.circuitBreaker,
        gate_reasons: run.gate.reasons,
        config_warnings: run.gate.warnings,
        config_errors: run.gate.configErrors,
      },
      stats: run.stats,
      forecast: run.forecast,
      write_summary: run.writeSummary,
      write_results: run.writeResults.map(({ would_send, ...r }) => r),
      alerts: {
        severity: run.alerts.dispatch.severity,
        slack: dispatchStatus('Post Slack Alert', run.alerts.dispatch.slack),
        webhook: dispatchStatus('Post Alert Webhook', run.alerts.dispatch.webhook),
      },
      contract_decisions: run.contracts.map((c) => ({
        source_deal_id: c.deal_id,
        company_id: c.company_id,
        contract_end_date: c.contract_end_date,
        days_until_expiration: c.days_until_expiration,
        arr: c.arr,
        status: c.status,
        milestone: c.milestone || null,
        provision_reason: c.provision_reason || null,
        duplicate_prevented: c.duplicate_prevented || null,
        existing_renewal_deal_id: c.existing_renewal ? c.existing_renewal.deal_id : null,
        created_renewal_deal_id: (run.createdRenewals || {})[c.idempotency_key] || null,
        stage_update: c.stage_update || null,
        renewal_owner_id: c.renewal_owner_id || null,
        owner_fallback_used: Boolean(c.owner_fallback_used),
        notes: c.notes,
      })),
      data_quality: run.dataQuality,
      fetch_warnings: run.fetchWarnings,
      rules_snapshot: { radar: run.config.radar, limits: run.config.limits, stage_map: run.config.hubspot.stageMap, renewal_pipeline_id: run.config.hubspot.renewalPipelineId },
    },
  },
}];
